package dev.livingrealms.sim.aviation;
import dev.livingrealms.sim.world.SimPosition;import java.util.*;
public final class AircraftMaterializationPlanner{private AircraftMaterializationPlanner(){}public static List<AircraftProjection> plan(Collection<AirWing> wings,Collection<SimPosition> players,double radius,int budget){Objects.requireNonNull(wings);Objects.requireNonNull(players);if(radius<=0||!Double.isFinite(radius)||budget<0)throw new IllegalArgumentException("planner config");if(players.isEmpty()||budget==0)return List.of();record Candidate(AirWing wing,double distance){}List<Candidate> c=new ArrayList<>();for(AirWing w:wings){if(w.destroyed())continue;double d=Double.POSITIVE_INFINITY;for(SimPosition p:players)d=Math.min(d,w.position().distanceTo(p));if(d<=radius)c.add(new Candidate(w,d));}c.sort(Comparator.comparingDouble(Candidate::distance).thenComparingLong(x->x.wing().id()));List<AircraftProjection> out=new ArrayList<>();int left=budget;for(Candidate x:c){int n=Math.min(Math.min(8,x.wing().aircraft()),left);for(int i=0;i<n;i++)out.add(new AircraftProjection(x.wing().id(),x.wing().factionId(),i,x.wing().model(),x.wing().position()));left-=n;if(left<=0)break;}return List.copyOf(out);}}
